// ---- dashboard rendering (real data only; unavailable data shows an explicit empty state) ----
let searchTerm='';
const pct=(n,t)=>t>0?(100*n/t).toFixed(1)+'%':'0%';
const fmtK=n=>n>=1e6?(n/1e6).toFixed(n%1e6?1:0)+'M':n>=1e3?(n/1e3).toFixed(n%1e3?1:0)+'k':String(n);
function niceStep(v){const p=Math.pow(10,Math.floor(Math.log10(Math.max(v,1))));for(const m of[1,2,5,10])if(m*p>=v)return m*p;return 10*p;}
function drawChart(points){const svg=$('trafficChart');const w=Math.max(320,svg.clientWidth||800),h=Math.max(180,svg.clientHeight||235),pl=44,pr=10,pt=10,pb=26,n=points.length;svg.setAttribute('viewBox',`0 0 ${w} ${h}`);
  const peak=Math.max(0,...points.map(p=>p.requests));const step=niceStep(Math.max(peak,4)/4),max=step*4;
  const x=i=>pl+i*(w-pl-pr)/Math.max(1,n-1),y=v=>pt+(h-pt-pb)*(1-v/max);
  let g='<defs><linearGradient id="gb" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#2f9bff" stop-opacity=".45"/><stop offset="1" stop-color="#2f9bff" stop-opacity="0"/></linearGradient><linearGradient id="gr" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#ff4d5e" stop-opacity=".5"/><stop offset="1" stop-color="#ff4d5e" stop-opacity="0"/></linearGradient></defs>';
  for(let k=0;k<=4;k++){const v=k*step,yy=y(v);g+=`<line x1="${pl}" y1="${yy}" x2="${w-pr}" y2="${yy}" stroke="#16304e"/><text x="${pl-8}" y="${yy+4}" text-anchor="end" font-size="11" fill="#8aa3c0">${fmtK(v)}</text>`;}
  const every=w<520?4:2;points.forEach((p,i)=>{if(i%every===0)g+=`<text x="${x(i)}" y="${h-7}" text-anchor="middle" font-size="11" fill="#8aa3c0">${escapeHtml(p.time)}</text>`;});
  const line=k=>points.map((p,i)=>`${x(i).toFixed(1)},${y(p[k]).toFixed(1)}`).join(' ');
  const area=k=>`M${x(0)},${y(0)} L${line(k).replace(/ /g,' L')} L${x(n-1)},${y(0)}Z`;
  if(n>1){g+=`<path d="${area('requests')}" fill="url(#gb)"/><path d="${area('blocked')}" fill="url(#gr)"/><polyline points="${line('requests')}" fill="none" stroke="#2f9bff" stroke-width="2.2" stroke-linejoin="round"/><polyline points="${line('blocked')}" fill="none" stroke="#ff4d5e" stroke-width="2" stroke-linejoin="round"/>`;}
  if(peak===0)g+=`<text x="${w/2}" y="${h/2}" text-anchor="middle" font-size="13" fill="#7e97b3">ยังไม่มีทราฟฟิกใน 24 ชั่วโมงที่ผ่านมา</text>`;
  svg.innerHTML=g;}
function actionBadge(x){return x.status===429?'<span class="badge limit">RATE LIMIT</span>':'<span class="badge block">BLOCK</span>';}
function eventRows(items){let list=items||[];if(searchTerm){const t=searchTerm.toLowerCase();list=list.filter(x=>[x.rule,x.ip,x.path,x.method].some(v=>String(v).toLowerCase().includes(t)));}
  return list.map(x=>`<tr><td>${escapeHtml(new Date(x.time).toLocaleString('th-TH',{hour12:false}))}</td><td><span class="type"><span class="dot" style="background:#ff4d5e"></span>${escapeHtml(x.rule)}</span></td><td>${escapeHtml(x.method)}</td><td>${escapeHtml(x.ip)}</td><td class="url" title="${escapeHtml(x.path)}">${escapeHtml(x.path)}</td><td>${actionBadge(x)}</td></tr>`).join('')||`<tr><td colspan="6" class="empty">${searchTerm?'ไม่พบเหตุการณ์ที่ตรงกับ “'+escapeHtml(searchTerm)+'”':'ยังไม่มีเหตุการณ์'}</td></tr>`;}
function render(d){snapshot=d;const total=d.totalRequests,blocked=d.blockedRequests;
  $('total').textContent=fmt(total);$('blocked').textContent=fmt(blocked);$('allowed').textContent=fmt(d.allowedRequests);$('rulesCount').textContent=fmt(d.activeRules);
  $('blockedPct').textContent=pct(blocked,total);$('allowedPct').textContent=pct(d.allowedRequests,total);
  $('status').textContent='ONLINE';$('droppedNote').textContent='Dropped events: '+fmt(d.droppedEvents);$('connection').textContent='ระบบออนไลน์';$('sysDot').classList.remove('off');
  const recent=d.recentEvents||[];$('bellCount').hidden=!recent.length;$('bellCount').textContent=recent.length>9?'9+':recent.length;
  $('donutTotal').textContent=fmt(blocked);const cats=d.threatCategories||[],sum=cats.reduce((a,b)=>a+b.count,0);let pos=0;
  const stops=cats.map((x,i)=>{const next=pos+(x.count/Math.max(sum,1))*100,r=`${palette[i%palette.length]} ${pos}% ${next}%`;pos=next;return r;});
  $('donut').style.background=stops.length?'conic-gradient('+stops.join(',')+')':'conic-gradient(#22374f 0 100%)';
  $('threatList').innerHTML=cats.length?cats.map((x,i)=>`<div class="threat-line"><span><span style="color:${palette[i%palette.length]}">●</span> ${escapeHtml(x.name)}</span><b>${fmt(x.count)}</b><i>${pct(x.count,sum)}</i></div>`).join(''):'<div class="empty">ยังไม่มีเหตุการณ์โจมตี</div>';
  const methods=d.methods||[],msum=methods.reduce((a,b)=>a+b.count,0),mmax=Math.max(1,...methods.map(x=>x.count));
  $('methods').innerHTML=methods.length?methods.slice(0,7).map(x=>`<div class="method-row"><span>${escapeHtml(x.name)}</span><div class="bar"><div style="width:${100*x.count/mmax}%"></div></div><b>${pct(x.count,msum)}</b></div>`).join(''):'<div class="empty">ยังไม่มีข้อมูลคำขอ</div>';
  $('recentRows').innerHTML=eventRows(recent.slice(0,8));
  const ips=d.topIps||[];$('ipRows').innerHTML=ips.map((x,i)=>`<tr><td>${i+1}</td><td>${escapeHtml(x.ip)}</td><td style="color:#ff6378">${fmt(x.blocked)}</td><td>${pct(x.blocked,blocked)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">ยังไม่มี IP ที่ถูกบล็อก</td></tr>';
  drawChart(d.timeline||[]);if(active!=='dashboard')loadSection();}
$('searchBox').addEventListener('keydown',e=>{if(e.key==='Enter'){searchTerm=e.target.value.trim();page(searchTerm?'events':active);if(snapshot)render(snapshot);}else if(e.key==='Escape'){e.target.value='';searchTerm='';e.target.blur();if(snapshot)render(snapshot);}});
