      return `<tr><td>${escapeHtml(site.siteId)}</td><td>${escapeHtml((site.hostnames||[]).join(', '))}</td><td>${upstreams}</td><td><span class="site-health-state site-health-${escapeHtml(String(state))}" title="${escapeHtml(explanation)}">${escapeHtml(label)}</span><small class="site-health-explanation">${escapeHtml(explanation)}</small></td><td>${escapeHtml(site.wafPolicy)}</td><td><button type="button" aria-label="ตรวจสอบ Health ของ ${escapeHtml(site.siteId)}" data-site-health="${escapeHtml(site.siteId)}">เช็ค Healthy</button> <button type="button" aria-label="แก้ไข Site ${escapeHtml(site.siteId)}" data-site-edit="${escapeHtml(site.siteId)}">แก้ไข</button> <button type="button" class="danger" aria-label="ลบ Site ${escapeHtml(site.siteId)}" data-site-delete="${escapeHtml(site.siteId)}">ลบ</button></td></tr>`;
